const root = $input.first().json ?? {};
const execution = root.execution ?? {};
const workflow = root.workflow ?? {};
const errorRaw = execution.error ?? root.error ?? root;

function asText(value, fallback = 'n/a') {
  if (value == null || value === '') return fallback;
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (value instanceof Error) return value.message || String(value);
  if (typeof value === 'object') {
    if (typeof value.message === 'string' && value.message.trim()) return value.message;
    if (typeof value.description === 'string' && value.description.trim()) return value.description;
    if (typeof value.error === 'string' && value.error.trim()) return value.error;
    try {
      return JSON.stringify(value);
    } catch {
      return fallback;
    }
  }
  return String(value);
}

const workflowName = asText(workflow.name ?? execution.workflowName, 'unknown');
const workflowId = asText(workflow.id ?? execution.workflowId, '');
const executionId = asText(execution.id ?? root.executionId, 'n/a');
const nodeName = asText(
  execution.lastNodeExecuted ?? errorRaw?.node ?? errorRaw?.nodeName ?? root.node?.name,
  'n/a'
);
const message = asText(
  errorRaw?.message ?? errorRaw?.description ?? errorRaw?.error ?? errorRaw,
  'Erro sem mensagem'
);
const startedAt = asText(execution.startedAt ?? root.startedAt, new Date().toISOString());
const n8nBase = String($env.N8N_BASE_URL || $env.WEBHOOK_URL || 'http://127.0.0.1:5678').replace(/\/$/, '');
const execUrl =
  typeof execution.url === 'string' && execution.url
    ? execution.url
    : `${n8nBase}/workflow/${workflowId}/executions/${executionId}`;

const text = [
  ':rotating_light: *Bethânia N8N — falha*',
  `*Workflow:* ${workflowName}`,
  `*Node:* ${nodeName}`,
  `*Erro:* ${message}`,
  `*Execution:* ${executionId}`,
  `*Quando:* ${startedAt}`,
  `*Link:* ${execUrl}`,
].join('\n');

const webhookUrl = String($env.BETHANIA_SLACK_WEBHOOK_URL || '').trim();
if (!webhookUrl) {
  throw new Error('BETHANIA_SLACK_WEBHOOK_URL não configurada');
}

return [{ json: { webhookUrl, text, workflowName, executionId, nodeName, message } }];
